def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Aggregate outcome counts and last move
    cc = cd = dc = dd = 0
    for mine, opp in history:
        if mine == 'C':
            if opp == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if opp == 'C':
                dc += 1
            else:
                dd += 1

    last_mine, last_opp = history[-1]

    # Count trailing opponent defections
    trail_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            trail_d += 1
        else:
            break

    # Count trailing mutual defections
    dd_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            dd_run += 1
        else:
            break

    opp_c = cc + dc
    opp_d = cd + dd
    coop_ratio = opp_c / float(n)
    defect_ratio = opp_d / float(n)

    # Phase 1: opening probes to distinguish key opponent classes quickly.
    # C first, then mirror-defect once to test retaliation, then return.
    if n == 1:
        return 'C'
    if n == 2 and history[0][1] == 'C' and history[1][1] == 'C':
        # Test whether opponent retaliates to a single defection
        return 'D'

    # If we just probed with D at round 3 (n==3 decision point reached)
    if n == 3:
        # If opponent retaliated (D) after our probe, back to C to show forgiveness
        # If they cooperated, they're exploitable: defect opportunistically later.
        return 'C'

    # Detect perfect always-cooperator (never defected)
    if opp_d == 0:
        # Exploit late, cooperate early to build value
        if n >= 90:
            return 'D'
        # occasional cheap exploitation safe from retaliation
        if n >= 30 and n % 7 == 0 and rng.random() < 0.55:
            return 'D'
        return 'C'

    # Detect near-total defector
    if coop_ratio <= 0.1:
        # Almost never cooperate; defect with rare probes
        if n % 13 == 0 and rng.random() < 0.10:
            return 'C'
        return 'D'

    # Strong always/near always D from start
    if defect_ratio >= 0.85:
        if n % 11 == 0 and rng.random() < 0.08:
            return 'C'
        return 'D'

    # Detect single-defection retaliators / TFT-like: they defected once and then
    # cooperated, and mirror our last move.
    if opp_d <= 2 and coop_ratio >= 0.75:
        # Highly cooperative, rare defections — reciprocate last move with forgiveness
        if last_opp == 'D':
            # Forgive after one-shot defection unless streak
            if trail_d >= 2:
                return 'D'
            # Retaliate once, then forgive
            if last_mine == 'C':
                return 'D'
            return 'C' if rng.random() < 0.65 else 'D'
        return 'C'

    # Sustained defector: fight back, but probe to escape DD lock-in
    if trail_d >= 4 or defect_ratio >= 0.6:
        # Break mutual defection cycles
        if dd_run >= 3:
            # Occasionally extend olive branch
            if rng.random() < 0.30:
                return 'C'
            return 'D'
        if last_opp == 'D':
            if rng.random() < 0.12:
                return 'C'
            return 'D'
        # Opponent cooperated: reward, but be wary of being exploited
        if defect_ratio >= 0.65:
            # still risky — sometimes exploit their cooperation
            if rng.random() < 0.30:
                return 'D'
            return 'C'
        return 'C'

    # General regime: tit-for-tat with forgiveness and endgame awareness
    if last_opp == 'C':
        if last_mine == 'D':
            # We defected, opponent cooperated — return to C to rebuild
            return 'C'
        # Opponent cooperated. Punish if pattern suggests exploitation.
        if n >= 3:
            if history[-1][1] == 'C' and history[-2][1] == 'C' and history[-3][1] == 'D':
                # Opponent oscillation: they cooperate after our C; not exploitative
                return 'C'
        # Probe occasionally
        if 20 <= n < 90 and n % 19 == 0 and rng.random() < 0.08:
            return 'D'
        return 'C'
    else:
        # Opponent defected
        if last_mine == 'C':
            # They exploited us. Retaliate strongly on repeat, forgive single.
            if trail_d >= 3:
                return 'D'
            if rng.random() < 0.80:
                return 'D'
            return 'C'
        else:
            # We already defected. Try to recover if not too far gone.
            if dd_run >= 3:
                if rng.random() < 0.40:
                    return 'C'
                return 'D'
            if dd_run == 2:
                if rng.random() < 0.30:
                    return 'C'
                return 'D'
            return 'D'
